WITH parsed AS (SELECT id, effective_from, tier_limits, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT CASE WHEN entry_price >= 29 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, DATE_TRUNC('YEAR', effective_from) AS year_start, PERCENTILE_APPROX(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, SUM(entry_price) AS total_entry_price, APPROX_PERCENTILE(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles_2, MIN(entry_price) AS min_entry_price, MIN(entry_price) AS min_entry_price_2 FROM parsed GROUP BY CASE WHEN entry_price >= 29 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', effective_from) HAVING SUM(entry_price) < 0 ORDER BY min_entry_price DESC
